# OVERVIEW: Optionally run three class-level unlearning update-scope baselines.
def forget_sets(records, label):
    forget=[r for r in records if r.source == 'AOL' and r.original_label == label]
    return forget,[r for r in records if r not in forget]
def choose_label():
    valid=[label for label in sorted(KNOWN_LABELS) if all(forget_sets(split,label)[0] for split in (train_records,val_records,test_records))]
    if not valid: raise ValueError('No AOL label occurs in all splits.')
    return random.Random(SEED).choice(valid)
def set_scope(branch, scope):
    for p in branch.parameters(): p.requires_grad=False
    modules={'head_only':[branch.classifier],'last_encoder_block':[branch.encoder.conv4,branch.encoder.conv4_4,branch.encoder.batch_norm4,branch.encoder.fc,branch.classifier],'full_encoder_and_head':[branch.encoder,branch.classifier]}[scope]
    for module in modules:
        for p in module.parameters(): p.requires_grad=True
def set_unlearning_train_mode(branch, scope):
    branch.train()
    if scope == 'head_only':
        branch.encoder.eval()  # Không cập nhật BatchNorm/Dropout encoder khi chỉ train MLP.
    elif scope == 'last_encoder_block':
        branch.encoder.eval()
        for module in (branch.encoder.conv4, branch.encoder.conv4_4, branch.encoder.batch_norm4, branch.encoder.max_pool_4, branch.encoder.dropout4, branch.encoder.fc):
            module.train()
        branch.classifier.train()
def forget_rate(branch, loader):
    branch.eval(); total=unknown=0
    with torch.no_grad():
        for batch in loader:
            features,mask,_=move(batch); logits,_=branch(features,mask); unknown += (torch.softmax(logits,1)[:,1] >= BEST_UNKNOWN_THRESHOLD).sum().item(); total += features.size(0)
    return unknown/max(total,1)
def run_single_scope(base_model, scope, ftr, rtr, fva, fte, rte, rep_seed, tag=''):
    """Train one unlearning baseline; returns (json-safe result, state_dict)."""
    seed_everything(rep_seed)
    branch=copy.deepcopy(base_model).to(DEVICE); set_scope(branch,scope); opt=torch.optim.AdamW([p for p in branch.parameters() if p.requires_grad],lr=UNLEARNING_LR,weight_decay=WEIGHT_DECAY); ce=nn.CrossEntropyLoss()
    f_loader,r_loader=make_loader(ftr,True),make_loader(rtr,True)
    best=copy.deepcopy(branch.state_dict()); best_score=-1.; history=[]
    for _epoch in range(UNLEARNING_EPOCHS):
        set_unlearning_train_mode(branch, scope); fi=iter(f_loader); ri=iter(r_loader)
        for _ in range(max(len(f_loader),len(r_loader))):
            try: fb=next(fi)
            except StopIteration: fi=iter(f_loader); fb=next(fi)
            try: rb=next(ri)
            except StopIteration: ri=iter(r_loader); rb=next(ri)
            fx,fm,_=move(fb); rx,rm,ry=move(rb); opt.zero_grad(set_to_none=True); fl,_=branch(fx,fm); rl,_=branch(rx,rm); loss=ce(fl,torch.ones(fl.size(0),dtype=torch.long,device=DEVICE))+RETAIN_LOSS_WEIGHT*ce(rl,ry); loss.backward(); nn.utils.clip_grad_norm_([p for p in branch.parameters() if p.requires_grad], max_norm=5.0); opt.step()
        _fr=forget_rate(branch,make_loader(fva,False)); _bal=evaluate(branch,make_loader(rva,False),BEST_UNKNOWN_THRESHOLD)['balanced_accuracy']; score=.5*(_fr+_bal)
        if score>best_score: best_score=score; best=copy.deepcopy(branch.state_dict())
        print(f'  {tag}[{scope}] epoch {_epoch+1}/{UNLEARNING_EPOCHS}: loss_last={loss.item():.4f} | Df-val forget_rate={_fr:.4f} | Dr-val bal_acc={_bal:.4f} | score={score:.4f} (best={best_score:.4f})')
        history.append({'epoch': _epoch+1, 'loss_last': float(loss.item()), 'df_val_forget_rate': _fr, 'dr_val_balanced_accuracy': _bal, 'score': score})
    branch.load_state_dict(best)
    result={'scope': scope, 'rep_seed': rep_seed, 'forget_as_unknown_test': forget_rate(branch,make_loader(fte,False)), 'retain_test': evaluate(branch,make_loader(rte,False),BEST_UNKNOWN_THRESHOLD), 'best_score': best_score, 'history': history}
    return result, copy.deepcopy(branch.state_dict())

def summarize_repeats(rep_results):
    forgets=[r['forget_as_unknown_test'] for r in rep_results]; bals=[r['retain_test']['balanced_accuracy'] for r in rep_results]; accs=[r['retain_test']['accuracy'] for r in rep_results]
    return {'n': len(rep_results), 'forget_mean': float(np.mean(forgets)), 'forget_std': float(np.std(forgets)), 'retain_bal_mean': float(np.mean(bals)), 'retain_bal_std': float(np.std(bals)), 'retain_acc_mean': float(np.mean(accs)), 'retain_acc_std': float(np.std(accs))}

if RUN_UNLEARNING:
    _valid_labels=[label for label in sorted(KNOWN_LABELS) if all(forget_sets(split,label)[0] for split in (train_records,val_records,test_records))]
    print(f'Candidate forget labels: {len(_valid_labels)}/{len(KNOWN_LABELS)} AOL labels')
    _forget_labels=list(FORGET_LABELS) if FORGET_LABELS else [FORGET_LABEL or choose_label()]
    print(f'Forget labels: {_forget_labels} | repeats per (label, scope): {UNLEARNING_REPEATS} | seeds: {[UNLEARNING_SEED_BASE + r for r in range(UNLEARNING_REPEATS)]}')
    _extended=len(_forget_labels) > 1 or UNLEARNING_REPEATS > 1
    _all_scopes={scope: [] for scope in UNLEARNING_SCOPES}
    _label_entries=[]
    for forget_label in _forget_labels:
        print('='*80); print(f'FORGET_LABEL={forget_label!r} (manual={FORGET_LABEL is not None or bool(FORGET_LABELS)})')
        ftr,rtr=forget_sets(train_records,forget_label); fva,rva=forget_sets(val_records,forget_label); fte,rte=forget_sets(test_records,forget_label)
        if not all((ftr,rtr,fva,rva,fte,rte)): raise ValueError(f'Empty Df/Dr for {forget_label}')
        print(f'Df/Dr sizes: train {len(ftr)}/{len(rtr)}, val {len(fva)}/{len(rva)}, test {len(fte)}/{len(rte)}')
        print(f'BEST_UNKNOWN_THRESHOLD={BEST_UNKNOWN_THRESHOLD:.2f}')
        _pre_forget={name: forget_rate(model,make_loader(recs,False)) for name,recs in [('Df-train',ftr),('Df-val',fva),('Df-test',fte)]}
        _pre_retain={name: evaluate(model,make_loader(recs,False),BEST_UNKNOWN_THRESHOLD) for name,recs in [('Dr-train',rtr),('Dr-val',rva),('Dr-test',rte)]}
        print('Pre-unlearning forget_rate (Df -> unknown):', {k: round(v,4) for k,v in _pre_forget.items()})
        print('Pre-unlearning retain:', {k: {'acc': round(v['accuracy'],4), 'bal_acc': round(v['balanced_accuracy'],4), 'known_rec': round(v['known_recall'],4), 'unk_rec': round(v['unknown_recall'],4)} for k,v in _pre_retain.items()})
        _entry={'forget_label': forget_label, 'split_sizes': {'ftr': len(ftr), 'rtr': len(rtr), 'fva': len(fva), 'rva': len(rva), 'fte': len(fte), 'rte': len(rte)}, 'pre_unlearning': {'forget_rate': _pre_forget, 'retain': {k: {m: v[m] for m in ('loss','accuracy','known_recall','unknown_recall','balanced_accuracy','total')} for k,v in _pre_retain.items()}}, 'scopes': {}}
        for scope in UNLEARNING_SCOPES:
            _reps=[]
            for rep in range(UNLEARNING_REPEATS):
                _seed=UNLEARNING_SEED_BASE+rep; _tag=f'{forget_label}/r{rep} ' if _extended else ''
                _res,_state=run_single_scope(model,scope,ftr,rtr,fva,fte,rte,_seed,_tag); _res['forget_label']=forget_label
                print(f'  {_tag}[{scope}] DONE (seed={_seed}): Df-test forget {_pre_forget["Df-test"]:.4f} -> {_res["forget_as_unknown_test"]:.4f} | Dr-test bal_acc {_pre_retain["Dr-test"]["balanced_accuracy"]:.4f} -> {_res["retain_test"]["balanced_accuracy"]:.4f} | Dr-test acc {_pre_retain["Dr-test"]["accuracy"]:.4f} -> {_res["retain_test"]["accuracy"]:.4f}')
                _root=UNLEARNING_ROOT/forget_label/f'repeat_{rep}' if _extended else UNLEARNING_ROOT
                directory=_root/scope; directory.mkdir(parents=True,exist_ok=True); torch.save({'model_state_dict':_state,**{k:v for k,v in _res.items() if k != 'history'}},directory/'unlearned_model.pt'); write_json(directory/'result.json',_res); (directory/'README.md').write_text(f'# {scope} unlearning baseline\n\nForget AOL label: `{forget_label}` (repeat {rep}, seed {_seed}). Df is trained toward binary unknown (1); Dr retains its original binary labels.\n', encoding='utf-8'); _reps.append(_res)
            _entry['scopes'][scope]={'repeats': _reps, 'aggregate': summarize_repeats(_reps)}
            _all_scopes[scope].extend(_reps)
            if len(_reps) > 1:
                _a=_entry['scopes'][scope]['aggregate']; print(f'  [{scope}] aggregate over {forget_label} x{len(_reps)}: forget={_a["forget_mean"]:.4f}±{_a["forget_std"]:.4f} | retain_bal={_a["retain_bal_mean"]:.4f}±{_a["retain_bal_std"]:.4f}')
        _label_entries.append(_entry)
    _grand={scope: summarize_repeats(rs) for scope,rs in _all_scopes.items() if rs}
    write_json(UNLEARNING_ROOT/'summary.json',{'forget_labels': [e['forget_label'] for e in _label_entries], 'best_unknown_threshold': BEST_UNKNOWN_THRESHOLD, 'repeats': UNLEARNING_REPEATS, 'seeds': [UNLEARNING_SEED_BASE + r for r in range(UNLEARNING_REPEATS)], 'aggregate': _grand, 'labels': _label_entries})
    print('AGGREGATE over labels x repeats:')
    for scope,a in _grand.items(): print(f'  [{scope}] n={a["n"]}: forget={a["forget_mean"]:.4f}±{a["forget_std"]:.4f} | retain_bal={a["retain_bal_mean"]:.4f}±{a["retain_bal_std"]:.4f} | retain_acc={a["retain_acc_mean"]:.4f}±{a["retain_acc_std"]:.4f}')
else:
    print('RUN_UNLEARNING=False; base model only.')
